def sound_for(name):
    """name: '<theme>_p<k>' or '<theme>_v<k>' -> (prompt, negative)."""
    base, extra = ITEM.get(name) or THEME[name.rsplit('_', 1)[0]]
    return base + QUAL, NEG + (', ' + extra if extra else '')
